"""Build secondary static pages. No framework or runtime dependency."""
from pathlib import Path
import re
home=Path('index.html').read_text()
header=re.search(r'<header.*?</header>',home,re.S).group()
footer=re.search(r'<footer.*?</footer>',home,re.S).group()
footer=re.sub(r'<button id="motion-toggle".*?</button>','',footer)
def page(path,title,body):
 prefix='/' if path == '404.html' else '../' if '/' in path else ''
 h=header.replace('href="./"',f'href="{prefix}index.html"').replace('href="#',f'href="{prefix}index.html#').replace('href="curriculo.html"',f'href="{prefix}curriculo.html"')
 f=footer.replace('href="#conteudo"',f'href="{prefix}index.html"').replace('href="privacidade.html"',f'href="{prefix}privacidade.html"')
 s=f'''<!doctype html><html lang="pt-BR" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — Guilherme Trajano</title><meta name="description" content="{title}. Portfólio pessoal de Guilherme Trajano."><meta name="color-scheme" content="light dark"><meta name="theme-color" content="#ffffff"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}index.css"><script src="{prefix}theme.js"></script><script src="{prefix}index.js" defer></script></head><body><a class="skip-link" href="#conteudo">Pular para o conteúdo</a>{h}<main class="reading" id="conteudo">{body}</main>{f}</body></html>'''
 if path == '404.html': s=s.replace('href="index.html', 'href="/index.html')
 p=Path(path);p.parent.mkdir(exist_ok=True,parents=True);p.write_text(s)
page('curriculo.html','Trajetória', '''<a class="back-link" href="index.html#sobre">Voltar ao portfólio</a><div class="cv-heading"><h1>Guilherme<br>Trajano.</h1><button class="button primary print-button" id="print-cv">Imprimir / salvar PDF</button></div><p class="lead">Desenvolvimento, dados e inteligência artificial. Experiência de negócio aplicada à construção de soluções.</p><div class="reading-meta"><a href="https://www.linkedin.com/in/trajanogui/">LinkedIn / trajanogui</a><a href="https://github.com/TrolljanO">GitHub / TrolljanO</a></div><h2>Perfil</h2><p>Minha trajetória conecta vendas, desenvolvimento de sistemas e IA aplicada a arquitetura e construção. A experiência comercial trouxe uma forma de trabalhar: entender o problema, ouvir quem vai usar e explicar as decisões com clareza.</p><h2>Experiência e atuação</h2><div class="cv-item"><span>Dados e IA</span><div><h3>Arquitetura e construção</h3><p>Atuação em dados e inteligência artificial no setor de arquitetura, engenharia e construção.</p></div></div><div class="cv-item"><span>Desenvolvimento</span><div><h3>Sistemas e aplicações</h3><p>Experiência com desenvolvimento Laravel e projetos independentes. Exploração de sistemas com IA, APIs e automação.</p></div></div><div class="cv-item"><span>Vendas e negócio</span><div><h3>Relacionamento e gestão comercial</h3><p>Trajetória em seguros e serviços financeiros, gestão comercial e empreendedorismo. Experiência em negociação, escuta e construção de relacionamentos.</p></div></div><h2>Projetos públicos</h2><div class="cv-item"><span>SDD-Buddy</span><div><h3>Da ideia à especificação</h3><p>Assistente que estrutura requisitos e planejamento por meio de conversas guiadas. Python, FastAPI e React.</p><a class="text-link" href="https://github.com/TrolljanO/sdd_vibe_converter">Repositório do projeto</a></div></div><div class="cv-item"><span>Micro-RAG</span><div><h3>Perguntas com fontes</h3><p>Busca em documentos e geração de respostas sobre gestão de estoques, com citações. Python, FastAPI e FAISS.</p><a class="text-link" href="https://github.com/TrolljanO/micro-rag-jump">Repositório do projeto</a></div></div><h2>Áreas de estudo</h2><p>Desenvolvimento de Sistemas — ETEC.<br>Ciência de Dados — Descomplica.</p><p class="print-note">Resumo de trajetória. A versão profissional detalhada está disponível no <a href="https://www.linkedin.com/in/trajanogui/">LinkedIn</a>.</p>''')
page('projetos/sdd-buddy.html','SDD-Buddy', '''<a class="back-link" href="../index.html#projetos">Voltar aos projetos</a><h1>SDD-Buddy</h1><p class="lead">Dar estrutura a uma ideia antes de começar a escrever o código.</p><div class="reading-meta"><span>Projeto aberto</span><span>Python / FastAPI / React</span></div><h2>O problema</h2><p>Uma conversa pode começar com uma boa ideia e terminar sem clareza sobre o que construir. Requisitos, decisões e critérios acabam espalhados.</p><h2>A proposta</h2><p>O SDD-Buddy conduz uma conversa por etapas: princípios, especificação, planejamento, tarefas e revisão. Cada etapa produz um artefato em Markdown que pode ser lido, discutido e aprovado.</p><blockquote>A conversa vira um documento que pode ser revisado.</blockquote><h2>Como foi estruturado</h2><p>A documentação descreve uma máquina de estados para controlar as etapas, uma API em FastAPI e uma interface em React. Os artefatos passam por aprovação e o estado da conversa é persistido em SQLite.</p><h2>O que observar</h2><p>O ponto de interesse é a passagem entre etapas: como uma resposta se transforma em requisito e como uma decisão fica registrada antes de orientar a implementação.</p><h2>Limites</h2><p>O projeto usa modelos de linguagem. Uma especificação gerada ainda precisa de revisão humana. O repositório reúne a implementação, instruções e testes; esta apresentação não reproduz seus resultados de execução.</p><a class="button primary" href="https://github.com/TrolljanO/sdd_vibe_converter" target="_blank" rel="noopener noreferrer">Explorar o repositório <span aria-hidden="true">↗</span></a><p class="print-note">Descrição baseada na documentação pública do projeto, consultada em outubro de 2026.</p>''')
page('projetos/micro-rag.html','Micro-RAG', '''<a class="back-link" href="../index.html#projetos">Voltar aos projetos</a><h1>Micro-RAG</h1><p class="lead">Uma resposta é mais útil quando é possível encontrar de onde ela veio.</p><div class="reading-meta"><span>Projeto aberto</span><span>Python / FastAPI / FAISS</span></div><h2>O problema</h2><p>Encontrar uma informação em documentos exige mais do que produzir uma resposta plausível. É preciso localizar o trecho relevante e permitir que a fonte seja conferida.</p><h2>A proposta</h2><p>O Micro-RAG responde perguntas sobre gestão de estoques usando uma coleção de documentos técnicos. Primeiro recupera trechos relacionados à pergunta; depois usa esse contexto para gerar a resposta e retornar citações.</p><blockquote>Documento → busca → contexto → resposta com fontes.</blockquote><h2>Como foi estruturado</h2><p>O serviço combina uma API em FastAPI, indexação vetorial com FAISS e um modelo de linguagem. O contrato da resposta inclui o texto, as citações e métricas da execução.</p><h2>O que observar</h2><p>A organização da resposta permite conferir os trechos consultados. As decisões de tamanho dos fragmentos, recuperação e tratamento de perguntas estão documentadas no repositório.</p><h2>Limites</h2><p>A cobertura depende dos documentos indexados e da qualidade da recuperação. Uma citação não elimina a necessidade de conferir se o trecho sustenta a resposta. As métricas publicadas no repositório não foram reproduzidas nesta apresentação.</p><a class="button primary" href="https://github.com/TrolljanO/micro-rag-jump" target="_blank" rel="noopener noreferrer">Explorar o repositório <span aria-hidden="true">↗</span></a><p class="print-note">Descrição baseada na documentação pública do projeto, consultada em outubro de 2026.</p>''')
page('privacidade.html','Privacidade', '''<a class="back-link" href="index.html">Voltar ao início</a><h1>Privacidade</h1><p class="lead">Um site pessoal, com leitura direta e escolhas simples.</p><h2>Neste site</h2><p>Esta versão não usa ferramentas de analytics, pixels de publicidade, cookies de rastreamento ou formulários. Fontes e ilustrações são servidas junto com as páginas.</p><p>As preferências de tema e movimento são guardadas no armazenamento local do seu navegador. Elas não são enviadas a um servidor. Você pode apagá-las pelas configurações de dados do navegador.</p><h2>Links externos</h2><p>Ao abrir GitHub, LinkedIn ou X, você passa a navegar em outro serviço, com suas próprias políticas. O site não incorpora feeds dessas plataformas.</p><h2>Conteúdo</h2><p>Este portfólio reúne projetos pessoais e informações de fontes públicas. Não representa o posicionamento de empregadores. As imagens dos projetos na página inicial são ilustrações conceituais.</p><h2>Contato</h2><p>Para conversar sobre o site ou apontar uma informação a corrigir, use o <a href="https://www.linkedin.com/in/trajanogui/">LinkedIn</a>.</p>''')
page('404.html','Página não encontrada', '''<a class="back-link" href="index.html">Voltar ao início</a><h1>Fora da folha.</h1><p class="lead">A página que você procurou não está aqui. O endereço pode ter mudado.</p><a class="button primary" href="index.html#projetos">Explorar os projetos <span aria-hidden="true">↗</span></a>''')
print('Built 5 secondary pages.')
